// bin
// "Return the binary representation of an integer."
//   >>> bin(2796202)  ->  '0b1010101010101010101010'
// Negative integers are rendered as '-0b' followed by the digits of |x|.
// ---------------------------------------------------------------

// Binary digits (most significant first, no prefix) of a non-negative integer; "0" for 0.
function BinDigits(n: int): string
  requires n >= 0
  decreases n
{
  if n < 2 then (if n == 0 then "0" else "1")
  else BinDigits(n / 2) + (if n % 2 == 0 then "0" else "1")
}

// "Return the binary representation of an integer."
function Bin(x: int): string
{
  if x < 0 then "-0b" + BinDigits(-x) else "0b" + BinDigits(x)
}

