// list.sort
// "Sort the list in ascending order and return None.
//  The sort is in-place (i.e. the list itself is modified) and stable
//  (i.e. the order of two equal elements is maintained).
//  If a key function is given, apply it once to each list item and sort
//  them, ascending or descending, according to their function values."
// Modeled as a stable insertion sort (ascending) under strict order `lt`
// on key values; the resulting sequence is the new contents of the list.
// ---------------------------------------------------------------

// Insert x into ascending t after every element whose key is not greater (stability).
function InsertByKey<T, K>(x: T, t: seq<T>, key: T -> K, lt: (K, K) -> bool): seq<T>
  decreases |t|
{
  if |t| == 0 then [x]
