function ListSortByKey<T, K>(s: seq<T>, key: T -> K, lt: (K, K) -> bool): seq<T>
  decreases |s|
{
  if |s| == 0 then []
  else InsertByKey(s[|s| - 1], ListSortByKey(s[..|s| - 1], key, lt), key, lt)
}
